/**
 * @param {string[]} words
 * @param {string} target
 * @param {number} startIndex
 * @return {number}
 */
var closestTarget = function(words, target, startIndex) {
    const n = words.length;

    for (let i = 0; i < n; i++) {
        if (words[i] === target) {
            const dist = Math.abs(i - startIndex);
            return Math.min(dist, n - dist);
        }
    }

    return -1;
};

/**
 * @param {string[]} words
 * @param {string} target
 * @param {number} startIndex
 * @return {number}
 */
var closestTarget = function(words, target, startIndex) {
    const n = words.length;
    let min = Infinity;

    for (let i = 0; i < n; i++) {
        if (words[i] === target) {
            const dist = Math.abs(i - startIndex);
            min = Math.min(min, dist, n - dist);
        }
    }

    if (min === Infinity) {
        return -1;
    }

    return min;
};

/**
 * @param {string[]} words
 * @param {string} target
 * @param {number} start
 * @return {number}
 */
var closestTarget = function(words, target, start) {
    const n = words.length;
    const len = Math.ceil(n / 2);

    for (let i = 0; i < len; i++) {
        if (words[(start - i + n) % n] === target || words[(start + i) % n] === target) {
            return i;
        }
    }

    return -1;
};

